import {
  Button as AriaButton,
  Label,
  Tag as AriaTag,
  TagGroup as AriaTagGroup,
  TagList,
  Text,
} from "react-aria-components";
import type {
  TagGroupProps as AriaTagGroupProps,
  TagProps as AriaTagProps,
} from "react-aria-components";
import { X } from "./icons";
import { createContext, useContext } from "react";
import type { ReactNode, Ref } from "react";
import "./TagGroup.css";

const TagGroupContext = createContext<"neutral" | "strong">("neutral");

export interface TagGroupProps
  extends Omit<AriaTagGroupProps, "className" | "children"> {
  /** Visual emphasis. Strong uses pill chips with a neutral solid selection.
   * @default "neutral"
   */
  variant?: "neutral" | "strong";
  /** Group label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /**
   * Helper text describing the group.
   *
   * React Aria provides the slot here (`TagGroupInner` hands `descriptionProps` to `TextContext`),
   * so this is the same `<Text slot="description">` every field in the library uses and the
   * `aria-describedby` wiring is borrowed rather than hand-rolled; not exposing it would subtract a
   * capability from the borrowed layer for no reason. Contrast `Slider` and the three `Color*` controls, where React Aria offers no slot at
   * all and the id has to be generated.
   */
  description?: string;
  /**
   * Tag list items. **Static** → `<Tag>` nodes; **dynamic** → pair with `items` and pass a
   * function that renders one item. This wrapper collapses RAC's TagGroup + TagList into one
   * component, so the TagList collection contract is re-exposed here (same shape as `Select`,
   * which collapses Select + ListBox the same way).
   */
  children?: ReactNode | ((item: object) => ReactNode);
  /**
   * Dynamic collection source. When given, each item renders through the `children` function
   * (omit it for static nodes). Passed straight through to RAC's TagList.
   */
  items?: Iterable<object>;
  /** Content shown when the list is empty. */
  renderEmptyState?: () => ReactNode;
  /** Optional extra class. sd-tag-group is always preserved. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function TagGroup({
  variant = "neutral",
  label,
  contextualHelp,
  description,
  children,
  items,
  renderEmptyState,
  className,
  ...props
}: TagGroupProps) {
  return (
    <TagGroupContext.Provider value={variant}>
      <AriaTagGroup
        {...props}
        data-variant={variant}
        className={className ? `sd-tag-group ${className}` : "sd-tag-group"}
      >
        {contextualHelp ? (
          <div className="sd-tag-group__label-group">
            {label && <Label className="sd-tag-group__label sd-type-label-medium">{label}</Label>}
            {contextualHelp}
          </div>
        ) : (
          label && <Label className="sd-tag-group__label sd-type-label-medium">{label}</Label>
        )}
        <TagList
          className="sd-tag-group__list"
          items={items}
          renderEmptyState={renderEmptyState}
        >
          {children}
        </TagList>
        {description && (
          <Text slot="description" className="sd-tag-group__description sd-type-caption-medium">
            {description}
          </Text>
        )}
      </AriaTagGroup>
    </TagGroupContext.Provider>
  );
}

export interface TagProps extends Omit<AriaTagProps, "className" | "children"> {
  /** Tag content. */
  children?: AriaTagProps["children"];
  /** Optional extra class. sd-tag-group__item is always preserved. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

// A tag reads one rung below the `label-medium` TagGroup label that names the set — CONTRASTIVE
// (`naming-convention.md` § The size axis defaults to `medium`).
export function Tag({ children, className, textValue, ...props }: TagProps) {
  const variant = useContext(TagGroupContext);
  return (
    <AriaTag
      {...props}
      data-variant={variant}
      textValue={textValue || (typeof children === "string" ? children : undefined)}
      className={
        className
          // One rung below the TagGroup label that names the set — CONTRASTIVE.
          ? `sd-tag-group__item sd-type-label-small ${className}`
          : "sd-tag-group__item sd-type-label-small"
      }
    >
      {(renderProps) => (
        <>
          {typeof children === "function" ? children(renderProps) : children}
          {renderProps.allowsRemoving && (
            <AriaButton slot="remove" className="sd-tag-group__remove">
              <X aria-hidden size="1em" />
            </AriaButton>
          )}
        </>
      )}
    </AriaTag>
  );
}

.sd-tag-group {
  display: flex;
  flex-direction: column;
  gap: var(--sd-tag-group-gap);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-tag-group__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-tag-group-label-group-gap);
}

.sd-tag-group__label {
  padding-inline: var(--sd-tag-group-text-padding-inline);
  color: var(--sd-tag-group-label-foreground);
}

.sd-tag-group__list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-tag-group-list-gap);
  outline: none;
}

.sd-tag-group__list[data-focus-visible] {
  border-radius: var(--sd-tag-group-list-radius-current);
  corner-shape: var(--sd-tag-group-list-shape-current);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* item = a Tag chip (compound sub-part; one BEM namespace under the parent). */
.sd-tag-group__item {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  gap: var(--sd-tag-group-item-gap);
  /* The small Button's box, as a floor: a tag matches it at rest but may wrap, and Button's
     fixed height would clip a wrapped label. */
  min-height: var(--sd-tag-group-item-min-height);
  padding: var(--sd-tag-group-item-padding-block) var(--sd-tag-group-item-padding-inline);
  background: var(--sd-tag-group-item-background);
  color: var(--sd-tag-group-item-foreground);
  border: var(--sd-tag-group-item-border-width) solid var(--sd-tag-group-item-border);
  border-radius: var(--sd-tag-group-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  white-space: normal;
  cursor: default;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-tag-group-item-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-tag-group-item-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
}

/* shared interaction state-layer (ADR-0009): a translucent overlay over the
   chip's solid fill, so hover reads identically to every other surface;
   pointer-events:none lets React Aria's press/select pass through to the remove button. */
.sd-tag-group__item::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-tag-group__item[data-hovered]::after {
  background: var(--sd-tag-group-item-state-hover-current);
}

.sd-tag-group__item[data-pressed]::after {
  background: var(--sd-tag-group-item-state-pressed-current);
}

.sd-tag-group__item[data-hovered] {
  border-color: var(--sd-tag-group-item-border-hover);
}

.sd-tag-group__item[data-selected] {
  background: var(--sd-tag-group-item-background-selected);
  color: var(--sd-tag-group-item-foreground-selected);
  border-color: var(--sd-tag-group-item-border-selected);
  --sd-tag-group-item-state-hover-current: var(--sd-state-hover-selected);
  --sd-tag-group-item-state-pressed-current: var(--sd-state-pressed-selected);
}

.sd-tag-group__item[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-tag-group__item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-tag-group__remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* A declared square that must STAY square: its radius is `full`, so any width the flex row takes
     back draws an ellipse and shrinks the hit area with it (under 16px on a long tag). Same idiom as the Avatar and Badge plates. */
  flex: 0 0 auto;
  width: var(--sd-tag-group-remove-size);
  height: var(--sd-tag-group-remove-size);
  padding: var(--sd-tag-group-remove-padding);
  background: var(--sd-tag-group-remove-background);
  color: var(--sd-tag-group-remove-foreground);
  border: var(--sd-tag-group-remove-border-width) solid transparent;
  border-radius: var(--sd-tag-group-remove-radius);
  corner-shape: round;
  font: inherit;
  line-height: var(--sd-tag-group-remove-line-height-none);
  cursor: pointer;
  position: relative;
  isolation: isolate;
  outline: none;
}

/* WCAG 2.2 (2.5.8) pointer target. The painted button is 16 (`remove.size`), and the floor may
   never size a painted element (`sys-tokens.md` control-target-minimum), so a transparent
   centred pseudo-element carries the target instead. Same idiom as ComboBox, DatePicker and
   DateRangePicker. The clearance is DERIVED from tokens rather than read off a render: 4 of
   overflow per side against `item.padding.inline` at `space.small` (12/10/12 across the brands),
   so it cannot reach the chip's border, and `list.gap` plus the next chip's padding lie beyond it;
   on the block axis `item.min-height` is `control-height.small` (32) around a 16 box, so 8 of
   half-clearance against 4. The token's `$description` names the render check and its story.
   `translate` rather than a `transform` translate, per component-contract.md section 6 rule 6. */
.sd-tag-group__remove::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  min-width: var(--sd-tag-group-remove-touch-target-size);
  min-height: var(--sd-tag-group-remove-touch-target-size);
}
/* Interaction state-layer overlay (ADR-0009). */
.sd-tag-group__remove::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-tag-group__remove[data-hovered]::after {
  background: var(--sd-tag-group-remove-state-hover-current, var(--sd-state-hover));
}

.sd-tag-group__remove[data-pressed]::after {
  background: var(--sd-tag-group-remove-state-pressed-current, var(--sd-state-pressed));
}

.sd-tag-group__remove[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-tag-group__description {
  padding-inline: var(--sd-tag-group-text-padding-inline);
  color: var(--sd-tag-group-description-foreground);
}

/* Strong filter chips retain React Aria's selection states and keyboard model. */
/* The list's ring radius, relayed so a variant can change it without rewriting the Cmp token. */
.sd-tag-group {
  --sd-tag-group-list-radius-current: var(--sd-tag-group-list-radius);
  --sd-tag-group-list-shape-current: superellipse(var(--sd-radius-curve));
}
.sd-tag-group[data-variant="strong"] {
  /* A relay, not a rewrite of the Cmp token, so a consumer's own list radius survives (§6 rule 5). */
  --sd-tag-group-list-radius-current: var(--sd-tag-group-item-radius-strong);
  /* A pill keeps the round curve: a superellipse would square its ends. */
  --sd-tag-group-list-shape-current: round;
}
.sd-tag-group__item[data-variant="strong"] {
  background: var(--sd-tag-group-item-background-strong);
  border-color: var(--sd-tag-group-item-border-strong);
  border-radius: var(--sd-tag-group-item-radius-strong);
  corner-shape: round;
  --sd-tag-group-item-state-hover-current: var(--sd-state-hover);
  --sd-tag-group-item-state-pressed-current: var(--sd-state-pressed);
}
.sd-tag-group__item[data-variant="strong"][data-selected] {
  background: var(--sd-tag-group-item-background-strong-selected);
  color: var(--sd-tag-group-item-foreground-strong-selected);
  border-color: var(--sd-tag-group-item-border-strong-selected);
  --sd-tag-group-item-state-hover-current: var(--sd-state-hover-on-neutral-strong);
  --sd-tag-group-item-state-pressed-current: var(--sd-state-pressed-on-neutral-strong);
  /* The remove glyph sits on the same strong fill, so its wash is the fill's own (§6 rule 7). */
  --sd-tag-group-remove-state-hover-current: var(--sd-state-hover-on-neutral-strong);
  --sd-tag-group-remove-state-pressed-current: var(--sd-state-pressed-on-neutral-strong);
}
